-- ============================================================================
-- COLORSHINE MES V2
-- 16_planning_thickness_matrix_plant2000_seed_v2.sql
-- FIX: REVIEW rows may contain incomplete source keys (e.g. source row 98).
--      They are stored for data cleansing but cannot become VALID/ACTIVE until fixed.
-- ============================================================================

-- Recover pgAdmin session if the previous seed failed inside BEGIN.
ROLLBACK;

SET search_path TO mes, public;
BEGIN;

-- REVIEW/staging rows must be preservable even when source Material/ProductGroup is missing.
ALTER TABLE mes.planning_thickness_matrix
    ALTER COLUMN material_code DROP NOT NULL,
    ALTER COLUMN product_group DROP NOT NULL;

-- VALID rows, however, must have usable master keys.
ALTER TABLE mes.planning_thickness_matrix
    DROP CONSTRAINT IF EXISTS ck_pln_thk_valid_required_fields;

ALTER TABLE mes.planning_thickness_matrix
    ADD CONSTRAINT ck_pln_thk_valid_required_fields
    CHECK (
        validation_status <> 'VALID'
        OR (
            NULLIF(BTRIM(material_code), '') IS NOT NULL
            AND BTRIM(material_code) <> '0'
            AND NULLIF(BTRIM(product_group), '') IS NOT NULL
            AND BTRIM(product_group) <> '0'
        )
    );

-- Remove prior Plant 2000 matrix rows from this source before clean reload.
-- Safe here because this is still master-data setup and no released planning run should reference it yet.
DELETE FROM mes.planning_thickness_matrix
WHERE plant_code = '2000'
  AND source_uuid IS NOT NULL;


COMMIT;

-- Verification
SELECT plant_code, validation_status, is_active, count(*)
FROM mes.planning_thickness_matrix
WHERE plant_code='2000'
GROUP BY plant_code, validation_status, is_active
ORDER BY validation_status, is_active;

-- The bad source row is intentionally retained as REVIEW/inactive rather than aborting the load.
SELECT source_row_no, source_uuid, material_code, product_group, coating_gsm,
       validation_status, is_active, validation_notes
FROM mes.planning_thickness_matrix
WHERE plant_code='2000' AND source_row_no=98;

SELECT count(*) AS total_matrix_rows
FROM mes.planning_thickness_matrix
WHERE plant_code='2000';